// Noxtcord local update toast
(function(){
try{
var U=NoxticordNative&&NoxticordNative.localUpdater;
if(!U)return;
function showToast(){
try{
if(!document.body){setTimeout(showToast,1000);return}
if(document.getElementById("nc-update-toast"))return;
var box=document.createElement("div");
box.id="nc-update-toast";
box.style.cssText="position:fixed;right:20px;bottom:20px;z-index:100001;background:#1e1f22;color:#dbdee1;padding:12px 16px;border-radius:8px;border:1px solid #2e3035;font-family:'gg sans','Noto Sans','Helvetica Neue',Helvetica,Arial,sans-serif;font-size:14px;display:flex;gap:12px;align-items:center;box-shadow:0 8px 16px rgba(0,0,0,.4);max-width:380px";
var t=document.createElement("span");
t.textContent=NCtr("Une mise à jour de Noxtcord est disponible.");
t.style.flex="1";
var b=document.createElement("button");
b.textContent=NCtr("Mettre à jour et redémarrer");
b.style.cssText="background:#5865f2;color:#fff;border:0;padding:6px 12px;border-radius:4px;cursor:pointer;font-size:13px;white-space:nowrap";
b.onclick=function(){try{b.disabled=true;b.textContent=NCtr("Redémarrage…");U.apply()}catch(e){}};
box.appendChild(t);box.appendChild(b);
document.body.appendChild(box);
setTimeout(function(){try{box.remove()}catch(e){}},180000);
}catch(e){}
}
U.onAvailable(function(){showToast()});
setTimeout(function(){try{U.check().then(function(r){if(r)showToast()}).catch(function(){})}catch(e){}},8000);
setInterval(function(){try{U.check().then(function(r){if(r)showToast()}).catch(function(){})}catch(e){}},20000);
}catch(e){}
})();
